import urllib.request, ssl, json, base64
SA="/var/run/secrets/kubernetes.io/serviceaccount"
tok=open(SA+"/token").read().strip()
ctx=ssl.create_default_context(cafile=SA+"/ca.crt")
def req(path):
    r=urllib.request.Request("https://kubernetes.default.svc"+path, headers={"Authorization":"Bearer "+tok})
    try:
        resp=urllib.request.urlopen(r, context=ctx, timeout=15)
        return resp.status, resp.read()
    except urllib.error.HTTPError as e:
        return e.code, e.read()[:1500]
